func  (this *xt) HandleErrors(code interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    //
    // spot: error
    //
    //     {
    //         "rc": 1,
    //         "mc": "AUTH_103",
    //         "ma": [],
    //         "result": null
    //     }
    //
    // spot: success
    //
    //     {
    //         "returnCode": 0,
    //         "msgInfo": "success",
    //         "error": null,
    //         "result": []
    //     }
    //
    // swap and future: error
    //
    //     {
    //         "returnCode": 1,
    //         "msgInfo": "failure",
    //         "error": {
    //             "code": "403",
    //             "msg": "invalid signature"
    //         },
    //         "result": null
    //     }
    //
    // swap and future: success
    //
    //     {
    //         "returnCode": 0,
    //         "msgInfo": "success",
    //         "error": null,
    //         "result": null
    //     }
    //
    // other:
    //
    //     {
    //         "rc": 0,
    //         "mc": "SUCCESS",
    //         "ma": [],
    //         "result": {}
    //     }
    //
    // {"returnCode":1,"msgInfo":"failure","error":{"code":"insufficient_balance","msg":"insufficient balance","args":[]},"result":null}
    //
    //
    var status interface{} = this.SafeStringUpper2(response, "msgInfo", "mc")
    if ccxt.IsTrue(ccxt.IsTrue(!ccxt.IsEqual(status, nil)) && ccxt.IsTrue(!ccxt.IsEqual(status, "SUCCESS"))) {
        var feedback interface{} = ccxt.Add(ccxt.Add(this.Id, " "), body)
        var err interface{} = this.SafeValue(response, "error", map[string]interface{} {})
        var spotErrorCode interface{} = this.SafeString(response, "mc")
        var errorCode interface{} = this.SafeString(err, "code", spotErrorCode)
        var spotMessage interface{} = this.SafeString(response, "msgInfo")
        var message interface{} = this.SafeString(err, "msg", spotMessage)
        this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
        this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), message, feedback)
        panic(ccxt.ExchangeError(feedback))
    }
    return nil
}
